head.b:skin:
:root{--bg:#090e18;--panel:#151e2c;--border:#283547;--ink:#f7f9ff;--sub:#9fadc0;--accent:#19bd9d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}img{max-width:100%;height:auto}input,button{font:inherit}.shell{max-width:1170px;padding:0 18px;margin:auto}.topbar{background:#101927;border-bottom:1px solid var(--border);position:sticky;top:0;z-index:5}.topinner{min-height:74px;display:flex;align-items:center;gap:25px;flex-wrap:wrap}.logo{font-weight:800;font-size:25px;letter-spacing:-1px}.logo em{font-style:normal;color:var(--accent)}.nav{display:flex;gap:20px;flex-wrap:wrap}.nav a{color:#cad6e5;font-size:14px}.search{margin-left:auto;display:flex;gap:7px}.search input{max-width:180px;background:#1f2a39;border:1px solid var(--border);padding:9px;color:white;border-radius:9px}.search button{border:0;border-radius:9px;background:var(--accent);color:#04271f;padding:9px 13px;font-weight:750;cursor:pointer}.hero{padding:62px 0;background:radial-gradient(circle at 80% 10%,#143c38,#111c2d 52%,#090e18)}.hero small{color:var(--accent);font-weight:800;text-transform:uppercase;letter-spacing:2px}.hero h1{font-size:clamp(34px,5vw,60px);letter-spacing:-2px;line-height:1.1;margin:12px 0}.hero p{max-width:700px;color:var(--sub)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:30px;padding-top:32px;padding-bottom:60px}.layout h2{font-size:24px}.sidebox{padding:20px;background:var(--panel);border:1px solid var(--border);border-radius:14px}.widget ul{padding-left:20px}.widget{margin-bottom:18px}.blog-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.blog-posts .post-outer,.blog-posts .post-outer-container{min-width:0;background:var(--panel);border:1px solid var(--border);border-radius:14px;overflow:hidden}.blog-posts .post{padding:16px}.blog-posts .post-title{font-size:18px;line-height:1.3;margin:0 0 10px}.post-body{color:var(--sub);overflow-wrap:anywhere}.post-body img{border-radius:10px;max-width:100%}.date-outer,.post-outer{min-width:0}.post-header,.post-footer{font-size:12px;color:var(--sub)}.blog-pager{display:flex;justify-content:space-between;margin-top:24px}.blog-pager a{background:var(--panel);padding:10px 14px;border-radius:9px}.footer{border-top:1px solid var(--border);color:var(--sub);padding:28px 0;font-size:13px}.footer a{color:white}.footer-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}body.item-view .blog-posts,body.static_page .blog-posts{display:block}body.item-view .blog-posts .post,body.static_page .blog-posts .post{padding:24px}body.item-view .post-body,body.static_page .post-body{font-size:17px;line-height:1.8}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #8cdbfa;outline-offset:3px}@media(max-width:1050px){.layout{grid-template-columns:1fr}.blog-posts{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:680px){.blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))}.topinner{padding:12px 0}.search{margin-left:0;width:100%}.search input{max-width:none;flex:1}}@media(max-width:420px){.blog-posts{grid-template-columns:1fr}.nav{gap:12px}}

/* Blogger default sharing controls should never expand into poster-sized icons. */
.post-share-buttons,.post-share-buttons-top,.post-share-buttons-bottom,
.share-buttons,.sharing-buttons,.post-footer .share-buttons,
.post-footer .post-share-buttons,.post-footer .sharing-buttons{display:none!important}
.post-footer,.post-header{overflow-wrap:anywhere}
.post-footer img,.post-header img{max-width:20px!important;max-height:20px!important;width:auto!important;height:auto!important}
.blog-posts .post-outer,.blog-posts .post-outer-container{align-self:start;min-width:0}
.blog-posts .post-body figure{margin:0 0 12px}
.blog-posts .post-body figure img{display:block;width:100%;max-height:360px;object-fit:cover}
.blog-posts .post-body p{margin:10px 0}
.blog-posts .post-body a{overflow-wrap:anywhere}
.blog-posts .post-title a{display:block}
.post-body .inext-media img,.post-body .inext-movie img{width:100%;max-height:420px;object-fit:contain;background:#0b1220}
body.item-view .blog-posts .post-outer,body.item-view .blog-posts .post-outer-container{max-width:100%}
